// ===== Configuração (preencha no seu n8n; nunca no repositório) =====
const CLIENT_ID = '';      // cliente OAuth do Google (tipo "Aplicativo da Web")
const CLIENT_SECRET = '';
const URL_EMISSAO = 'https://exemplo.com/webhook/emitir';  // o login volta em URL_EMISSAO + '-login'
const PERMITIDOS = [];     // e-mails ('ana@escola.com') ou domínios inteiros ('@escola.com')
// ====================================================================

// Login com a conta Google (OAuth, fluxo de código). Quem cuida de senha e de
// tentativas é o Google; aqui só se confere se o e-mail está em PERMITIDOS.
const SESSAO = 8 * 3600000;   // ms que o login vale
const ESPERA = 10 * 60000;    // ms para concluir o login no Google
const MAX_ESPERAS = 500;      // logins pendentes guardados ao mesmo tempo

const item = $input.first().json;
const aleatorio = String(item.aleatorio || '').replace(/[^A-Za-z0-9]/g, '');
const LOGIN = URL_EMISSAO + '-login';
const negar = (status, mensagem) => [{ json: { acao: 'negar', status, mensagem } }];
const cookie = (nome, valor, ms) =>
  `${nome}=${valor}; Path=/webhook/; Max-Age=${Math.floor(ms / 1000)}; HttpOnly; Secure; SameSite=Lax`;
const esc = v => String(v ?? '').replace(/[&<>"']/g, c =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

if (!CLIENT_ID || !CLIENT_SECRET || !PERMITIDOS.length) return negar(404, 'Não encontrado.');
if (aleatorio.length < 80) return negar(503, 'Tente de novo.');

// ponytail: sessões e logins pendentes nos dados estáticos do fluxo, sem botão
// "sair" (o login vale SESSAO). Tirar um e-mail de PERMITIDOS corta o acesso na
// hora, porque cada acesso confere a lista de novo.
const dados = $getWorkflowStaticData('global');
const agora = Date.now();
const sessoes = dados.sessoes || {};
const esperas = dados.esperas || {};
for (const k of Object.keys(sessoes)) if (sessoes[k].exp <= agora) delete sessoes[k];
for (const k of Object.keys(esperas)) if (esperas[k] <= agora) delete esperas[k];
dados.sessoes = sessoes;
dados.esperas = esperas;

const permitido = email => PERMITIDOS.some(p => p.startsWith('@')
  ? email.endsWith(p.toLowerCase()) : email === p.toLowerCase());

const cookies = {};
for (const par of String((item.headers || {}).cookie || '').split(';')) {
  const i = par.indexOf('=');
  if (i > 0) cookies[par.slice(0, i).trim()] = par.slice(i + 1).trim();
}


// Tela com o botão "Fazer login com o Google" (padrão visual do Google, sem
// script: é um link). Cada exibição abre um login pendente, com state próprio.
function telaLogin(status, aviso) {
  if (Object.keys(esperas).length >= MAX_ESPERAS) return negar(429, 'Muitas tentativas. Aguarde alguns minutos.');
  esperas[aleatorio] = agora + ESPERA;
  const params = { client_id: CLIENT_ID, redirect_uri: LOGIN, response_type: 'code', scope: 'openid email',
    state: aleatorio, prompt: 'select_account' };
  const google = 'https://accounts.google.com/o/oauth2/v2/auth?' + Object.entries(params)
    .map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&');
  // O HTML da tela fica no subfluxo "Emitir documento: telas"; aqui só os valores, já escapados.
  return [{ json: { acao: 'entrar', tela: 'login', status, cookie: cookie('emissao_login', aleatorio, ESPERA),
    google: esc(google), aviso: esc(aviso) } }];
}

// 3) Volta do Google, já com o e-mail confirmado pelo fluxo principal.
if (item.sub && 'email_verified' in item) {
  const email = String(item.email || '').toLowerCase();
  if (item.email_verified !== true || !permitido(email)) {
    return telaLogin(403, `A conta ${email} não tem acesso à emissão. Entre com a conta da equipe.`);
  }
  // Parte do aleatório vira a chave da sessão (cookie); o resto, o token dos formulários.
  sessoes[aleatorio.slice(0, 40)] = { email, exp: agora + SESSAO, csrf: aleatorio.slice(40) };
  return [{ json: { acao: 'redirecionar', location: URL_EMISSAO, cookie: cookie('emissao', aleatorio.slice(0, 40), SESSAO) } }];
}

// 2) Google devolveu o código: confere o state (o mesmo do cookie deste navegador).
if (String(item.webhookUrl || '').endsWith('-login')) {
  const q = item.query || {};
  const state = String(q.state || '');
  const valido = state && cookies.emissao_login === state && esperas[state] > agora;
  if (state) delete esperas[state];
  if (!valido || !q.code) return telaLogin(400, 'O login expirou ou foi cancelado. Entre de novo.');
  return [{ json: { acao: 'trocar', code: String(q.code), client_id: CLIENT_ID, client_secret: CLIENT_SECRET,
    redirect_uri: LOGIN } }];
}

// 1) Página da emissão: com sessão válida, segue; sem, tela de login.
// O n8n serve as páginas com a CSP "sandbox" (origem opaca), e o navegador não manda
// o cookie SameSite=Lax nos POST. Por isso o POST se identifica pelo token da sessão,
// num campo oculto do formulário, que outro site não conhece.
const csrf = String((item.body || {}).csrf || '');
const chave = csrf ? Object.keys(sessoes).find(k => sessoes[k].csrf === csrf) : cookies.emissao;
const s = chave && Object.hasOwn(sessoes, chave) ? sessoes[chave] : null;
if (s && permitido(s.email)) {  // segue com o pedido (e o CSV enviado, se houver)
  return [{ json: { acao: 'ok', email: s.email, csrf: s.csrf || '', query: item.query || {}, body: item.body || {} }, binary: $input.first().binary }];
}
return telaLogin(200);
